import re

def parse(lines):
    rows = []
    used = []
    skip = []
    rx = re.compile(r'^(?P<c>\S+)\s+(?P<i>\d+)\s+(?P<h>\S+)\s+(?P<d>\S+)\s+(?P<s>\S+)\s+(?P<t>\S+)(?:\s+(?P<desc>\S.*?))?\s*$')
    for i, l in enumerate(lines):
        s = l.strip()
        if not s:
            continue
        if re.match(r'^Class\s+I\s+H/W', l) or re.match(r'^[=\-]+$', s):
            skip.append(i)
            continue
        if not l[0].isspace():
            m = rx.match(l)
            if m:
                rows.append({'Class': m.group('c'), 'I': m.group('i'), 'H/W Path': m.group('h'), 'Driver': m.group('d'), 'S/W State': m.group('s'), 'H/W Type': m.group('t'), 'Description': re.sub(r'\s+', ' ', m.group('desc') or ''), 'Block Device': '', 'Raw Device': ''})
                used.append(i)
            continue
        if rows:
            r = rows[-1]
            for p in s.split():
                if '/rdsk/' in p or '/rdisk/' in p:
                    k = 'Raw Device'
                else:
                    k = 'Block Device'
                r[k] = (r[k] + ' ' + p).strip()
            used.append(i)
    blocks = []
    if rows:
        blocks.append({'name': 'disks', 'kind': 'table', 'lines': used, 'records': rows})
    return {'blocks': blocks, 'skip': skip}
